contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint dep, uint am) public payable {
        require(address(this).balance >= dep, "insufficient test balance");

        // record starting balances
        uint beforeCallerBal = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // perform a deposit so the collect precondition can be met; this is a state-changing call
        if (dep > 0) {
            c.Deposit{value: dep}();
        }

        // record after-deposit balances before the deciding collect
        uint midCallerBal = c.balances(address(this));
        uint midContractBal = address(c).balance;

        // deciding collect call: may revert, so wrap in try/catch
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }

        // read public balances after the collect attempt
        uint afterCallerBal = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        if (reverted) {
            assert(afterCallerBal == midCallerBal && afterContractBal == midContractBal);
        } else {
            assert(afterCallerBal == midCallerBal - am && afterContractBal == midContractBal - am);
        }
    }

    receive() external payable {}
}

