        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        bool creditNotIncreased = balAfter <= balBefore;
        bool etherNotIncreased = cBalAfter <= cBalBefore;

        bool revertedAndUnchanged =
            reverted &&
            balAfter == balBefore &&
            cBalAfter == cBalBefore;

        bool successAndDecreased =
            !reverted &&
            am <= balBefore &&
            balAfter == balBefore - am &&
            cBalAfter == cBalBefore - am;

        assert(creditNotIncreased && etherNotIncreased && (revertedAndUnchanged || successAndDecreased));
    }

    receive() external payable {}
}

